2	 1 │ /**
3	 2 │  * Duplicate key: title trimmed and lower-cased, plus due date.
4	 3 │  * Mirrors the database's unique index on (user_id, lower(title), due_date).
5	 4 │  */
6	 5 │ export function dedupeKey(title: string, dueDate: string): string {
7	 6 │   return `${title.trim().toLowerCase()}\u0000${dueDate}`;
8	 7 │ }
9	 8 │ 
10	 9 │ type Dedupable = { rowNumber: number; task: { title: string; due_date: string } };
11	10 │ 
12	11 │ /** Splits rows into first occurrences and later copies (each pointing at the first). */
13	12 │ export function findInFileDuplicates<T extends Dedupable>(items: T[]) {
14	13 │   const firstRowByKey = new Map<string, number>();
15	14 │   const unique: T[] = [];
16	15 │   const duplicates: { item: T; firstRowNumber: number }[] = [];
17	16 │ 
18	17 │   for (const item of items) {
19	18 │     const key = dedupeKey(item.task.title, item.task.due_date);
20	19 │     const firstRowNumber = firstRowByKey.get(key);
21	20 │     if (firstRowNumber === undefined) {
22	21 │       firstRowByKey.set(key, item.rowNumber);
23	22 │       unique.push(item);
24	23 │     } else {
25	24 │       duplicates.push({ item, firstRowNumber });
26	25 │     }
27	26 │   }
28	27 │ 
29	28 │   return { unique, duplicates };
30	29 │ }
