65	 34 │ /** Pure part of the import: parse, validate every row, and remove in-file duplicates. */
66	 35 │ export function planImport(text: string): { ok: true; plan: ImportPlan } | { ok: false; error: string } {
67	 36 │   const parsed = parseCsv(text);
68	 37 │   if (!parsed.ok) return parsed;
69	 38 │ 
70	 39 │   if (parsed.rows.length > MAX_DATA_ROWS) {
71	 40 │     return {
72	 41 │       ok: false,
73	 42 │       error: `The file has ${parsed.rows.length} rows. The limit is ${MAX_DATA_ROWS}.`,
74	 43 │     };
75	 44 │   }
76	 45 │ 
77	 46 │   const rejected: RejectedRow[] = [];
78	 47 │   const valid: ImportCandidate[] = [];
79	 48 │   for (const row of parsed.rows) {
80	 49 │     const result = validateTaskInput(row.fields);
81	 50 │     if (result.ok) valid.push({ rowNumber: row.rowNumber, cells: row.cells, task: result.value });
82	 51 │     else rejected.push({ rowNumber: row.rowNumber, cells: row.cells, reasons: result.errors });
83	 52 │   }
84	 53 │ 
85	 54 │   const { unique, duplicates } = findInFileDuplicates(valid);
86	 55 │   for (const { item, firstRowNumber } of duplicates) {
87	 56 │     rejected.push({ rowNumber: item.rowNumber, cells: item.cells, reasons: [duplicateOfRow(firstRowNumber)] });
88	 57 │   }
89	 58 │ 
90	 59 │   return {
91	 60 │     ok: true,
92	 61 │     plan: {
93	 62 │       headers: parsed.headers,
94	 63 │       candidates: unique,
95	 64 │       rejected: rejected.sort(byRowNumber),
96	 65 │       blankSkipped: parsed.blankSkipped,
97	 66 │     },
98	 67 │   };
99	 68 │ }
100	 69 │ 
101	 70 │ type ImportRpcResult = { inserted: number; skipped_row_numbers: number[] };
102	 71 │ 
103	 72 │ /**
104	 73 │  * Full import as the signed-in user: plan in TypeScript, then insert every valid row in one
105	 74 │  * database call (one transaction). Rows that clash with an existing live task come back as skipped.
106	 75 │  */
107	 76 │ export async function runImport(supabase: SupabaseClient, text: string): Promise<ImportResult> {
108	 77 │   const planned = planImport(text);
109	 78 │   if (!planned.ok) return planned;
110	 79 │   const { plan } = planned;
111	 80 │ 
112	 81 │   let imported = 0;
113	 82 │   const rejected = [...plan.rejected];
114	 83 │ 
115	 84 │   if (plan.candidates.length > 0) {
116	 85 │     const rows = plan.candidates.map((c) => ({ row_number: c.rowNumber, ...c.task }));
117	 86 │     const { data, error } = await supabase.rpc("import_tasks", { rows });
118	 87 │     if (error) {
119	 88 │       console.error("import_tasks failed", { code: error.code, message: error.message });
120	 89 │       return { ok: false, error: "The import failed and no rows were saved. Please try again." };
121	 90 │     }
122	 91 │     const result = data as ImportRpcResult;
123	 92 │     imported = result.inserted;
124	 93 │     const skipped = new Set(result.skipped_row_numbers);
125	 94 │     for (const candidate of plan.candidates) {
126	 95 │       if (skipped.has(candidate.rowNumber)) {
127	 96 │         rejected.push({ rowNumber: candidate.rowNumber, cells: candidate.cells, reasons: [ALREADY_EXISTS] });
128	 97 │       }
129	 98 │     }
130	 99 │   }
131	100 │ 
132	101 │   return {
133	102 │     ok: true,
134	103 │     imported,
135	104 │     blankSkipped: plan.blankSkipped,
136	105 │     headers: plan.headers,
137	106 │     rejected: rejected.sort(byRowNumber),
138	107 │   };
139	108 │ }
