141	 1 │ import Papa from "papaparse";
142	 2 │ import { KNOWN_COLUMNS, REQUIRED_COLUMNS, type CsvColumn, type ParseResult, type ParsedRow } from "./types";
143	 3 │ 
144	 4 │ const BOM = "﻿";
145	 5 │ 
146	 6 │ function isBlank(cells: string[]): boolean {
147	 7 │   return cells.every((cell) => cell.trim() === "");
148	 8 │ }
149	 9 │ 
150	10 │ /**
151	11 │  * Parses CSV text into rows keyed by known column.
152	12 │  * Row numbers count every record (blank ones included), so they match what a spreadsheet shows
153	13 │  * even when a quoted cell spans several lines.
154	14 │  */
155	15 │ export function parseCsv(input: string): ParseResult {
156	16 │   const withoutBom = input.startsWith(BOM) ? input.slice(BOM.length) : input;
157	17 │   // Normalise line endings so files mixing CRLF and LF parse consistently.
158	18 │   const text = withoutBom.replace(/\r\n?/g, "\n");
159	19 │   if (text.trim() === "") return { ok: false, error: "The file is empty." };
160	20 │ 
161	21 │   const parsed = Papa.parse<string[]>(text, { header: false, skipEmptyLines: false, newline: "\n" });
162	22 │ 
163	23 │   const quoteError = parsed.errors.find((e) => e.type === "Quotes");
164	24 │   if (quoteError) {
165	25 │     const row = quoteError.row === undefined ? "" : ` near row ${quoteError.row + 1}`;
166	26 │     return { ok: false, error: `The file has an unclosed quote${row}, so it can't be read reliably.` };
167	27 │   }
168	28 │ 
169	29 │   const records = parsed.data;
170	30 │   // A trailing newline yields one final empty record; it isn't a row.
171	31 │   const last = records.at(-1);
172	32 │   if (records.length > 1 && last && last.length === 1 && last[0] === "") records.pop();
173	33 │ 
174	34 │   // Skip any blank lines before the header.
175	35 │   const headerIndex = records.findIndex((cells) => !isBlank(cells));
176	36 │   if (headerIndex === -1) return { ok: false, error: "The file is empty." };
177	37 │ 
178	38 │   const headers = records[headerIndex].map((h) => h.trim());
179	39 │   const columnIndex = new Map<CsvColumn, number>();
180	40 │   headers.forEach((header, index) => {
181	41 │     const key = header.toLowerCase() as CsvColumn;
182	42 │     if ((KNOWN_COLUMNS as readonly string[]).includes(key) && !columnIndex.has(key)) {
183	43 │       columnIndex.set(key, index);
184	44 │     }
185	45 │   });
186	46 │ 
187	47 │   const missing = REQUIRED_COLUMNS.filter((column) => !columnIndex.has(column));
188	48 │   if (missing.length > 0) {
189	49 │     const label = missing.length === 1 ? "column" : "columns";
190	50 │     return {
191	51 │       ok: false,
192	52 │       error: `Missing required ${label}: ${missing.join(", ")}. Expected columns: ${KNOWN_COLUMNS.join(", ")}.`,
193	53 │     };
194	54 │   }
195	55 │ 
196	56 │   const rows: ParsedRow[] = [];
197	57 │   let blankSkipped = 0;
198	58 │   for (let i = headerIndex + 1; i < records.length; i++) {
199	59 │     const cells = records[i];
200	60 │     if (isBlank(cells)) {
201	61 │       blankSkipped++;
202	62 │       continue;
203	63 │     }
204	64 │     const cellAt = (column: CsvColumn) => {
205	65 │       const index = columnIndex.get(column);
206	66 │       return index === undefined ? "" : (cells[index] ?? "");
207	67 │     };
208	68 │     rows.push({
209	69 │       rowNumber: i + 1,
210	70 │       cells,
211	71 │       fields: {
212	72 │         title: cellAt("title"),
213	73 │         due_date: cellAt("due_date"),
214	74 │         priority: cellAt("priority"),
215	75 │         notes: cellAt("notes"),
216	76 │       },
217	77 │     });
218	78 │   }
219	79 │ 
220	80 │   return { ok: true, headers, rows, blankSkipped };
221	81 │ }
