506	 28 │ export type ValidationResult =
507	 29 │   | { ok: true; value: TaskInput }
508	 30 │   | { ok: false; errors: string[] };
509	 31 │ 
510	 32 │ export const MESSAGES = {
511	 33 │   titleRequired: "title is required",
512	 34 │   titleTooLong: `title must be ${TITLE_MAX_LENGTH} characters or fewer`,
513	 35 │   dueDateRequired: "due_date is required",
514	 36 │   dueDateInvalid: "due_date must be a real date in YYYY-MM-DD format",
515	 37 │   priorityRequired: "priority is required",
516	 38 │   priorityInvalid: "priority must be a whole number from 1 to 5",
517	 39 │   notesTooLong: `notes must be ${NOTES_MAX_LENGTH} characters or fewer`,
518	 40 │ } as const;
519	 41 │ 
520	 42 │ const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
521	 43 │ const PRIORITY_PATTERN = /^[1-5]$/;
522	 44 │ 
523	 45 │ function asTrimmedString(value: unknown): string {
524	 46 │   if (value === null || value === undefined) return "";
525	 47 │   return String(value).trim();
526	 48 │ }
527	 49 │ 
528	 50 │ /** True when `value` is YYYY-MM-DD and names a day that exists on the calendar. */
529	 51 │ export function isValidIsoDate(value: string): boolean {
530	 52 │   const match = DATE_PATTERN.exec(value);
531	 53 │   if (!match) return false;
532	 54 │   const [year, month, day] = match.slice(1).map(Number);
533	 55 │   // Year 0 doesn't exist in Postgres's (proleptic Gregorian, AD) date type.
534	 56 │   if (year < 1) return false;
535	 57 │   const date = new Date(0);
536	 58 │   // setUTCFullYear avoids Date.UTC's 0–99 → 1900–1999 mapping.
537	 59 │   date.setUTCFullYear(year, month - 1, day);
538	 60 │   return (
539	 61 │     date.getUTCFullYear() === year &&
540	 62 │     date.getUTCMonth() === month - 1 &&
541	 63 │     date.getUTCDate() === day
542	 64 │   );
543	 65 │ }
