545	 67 │ /** Validates every field and returns all failure reasons, not just the first. */
546	 68 │ export function validateTaskInput(raw: RawTaskInput): ValidationResult {
547	 69 │   const errors: string[] = [];
548	 70 │ 
549	 71 │   const title = asTrimmedString(raw.title);
550	 72 │   if (title === "") errors.push(MESSAGES.titleRequired);
551	 73 │   else if ([...title].length > TITLE_MAX_LENGTH) errors.push(MESSAGES.titleTooLong);
552	 74 │ 
553	 75 │   const dueDate = asTrimmedString(raw.due_date);
554	 76 │   if (dueDate === "") errors.push(MESSAGES.dueDateRequired);
555	 77 │   else if (!isValidIsoDate(dueDate)) errors.push(MESSAGES.dueDateInvalid);
556	 78 │ 
557	 79 │   const priorityText = asTrimmedString(raw.priority);
558	 80 │   if (priorityText === "") errors.push(MESSAGES.priorityRequired);
559	 81 │   else if (!PRIORITY_PATTERN.test(priorityText)) errors.push(MESSAGES.priorityInvalid);
560	 82 │ 
561	 83 │   const notes = asTrimmedString(raw.notes);
562	 84 │   if ([...notes].length > NOTES_MAX_LENGTH) errors.push(MESSAGES.notesTooLong);
563	 85 │ 
564	 86 │   if (errors.length > 0) return { ok: false, errors };
565	 87 │ 
566	 88 │   return {
567	 89 │     ok: true,
568	 90 │     value: {
569	 91 │       title,
570	 92 │       due_date: dueDate,
571	 93 │       priority: Number(priorityText),
572	 94 │       notes: notes === "" ? null : notes,
573	 95 │     },
574	 96 │   };
575	 97 │ }
576	 98 │ 
577	 99 │ export function isTaskStatus(value: unknown): value is TaskStatus {
