605	 5 │ const PUBLIC_PATHS = ["/login"];
606	 6 │ 
607	 7 │ /**
608	 8 │  * Refreshes the Supabase session cookie and makes an optimistic redirect.
609	 9 │  * This is not the authorisation check: requireUser() and RLS are.
610	10 │  */
611	11 │ export async function proxy(request: NextRequest) {
612	12 │   let response = NextResponse.next({ request });
613	13 │   const { url, publishableKey } = supabaseEnv();
614	14 │ 
615	15 │   const supabase = createServerClient(url, publishableKey, {
616	16 │     cookies: {
617	17 │       getAll() {
618	18 │         return request.cookies.getAll();
619	19 │       },
620	20 │       setAll(cookiesToSet, headers) {
621	21 │         for (const { name, value } of cookiesToSet) request.cookies.set(name, value);
622	22 │         response = NextResponse.next({ request });
623	23 │         for (const { name, value, options } of cookiesToSet) response.cookies.set(name, value, options);
624	24 │         for (const [key, value] of Object.entries(headers ?? {})) response.headers.set(key, value);
625	25 │       },
626	26 │     },
627	27 │   });
628	28 │ 
629	29 │   // getClaims validates the JWT and refreshes an expired session (writing new cookies above).
630	30 │   const { data } = await supabase.auth.getClaims();
631	31 │   const signedIn = Boolean(data?.claims);
632	32 │   const { pathname } = request.nextUrl;
633	33 │   const isPublic = PUBLIC_PATHS.some((p) => pathname === p || pathname.startsWith(`${p}/`));
634	34 │ 
635	35 │   if (!signedIn && !isPublic) return redirectKeepingCookies(request, response, "/login");
636	36 │   if (signedIn && isPublic) return redirectKeepingCookies(request, response, "/tasks");
637	37 │   return response;
638	38 │ }
