640	40 │ function redirectKeepingCookies(request: NextRequest, from: NextResponse, pathname: string) {
641	41 │   const target = request.nextUrl.clone();
642	42 │   target.pathname = pathname;
643	43 │   target.search = "";
644	44 │   const redirect = NextResponse.redirect(target);
645	45 │   for (const cookie of from.cookies.getAll()) redirect.cookies.set(cookie);
646	46 │   return redirect;
647	47 │ }
